pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testRegression_property() public {

        address rewardToken = address(0x123);
        c.addReward(rewardToken);

        address newDistributor = address(0x456);
        vm.prank(address(this));
        c.setRewardDistributor(newDistributor);

        vm.prank(newDistributor);

        bool ok;

        assertTrue(c.rewardDistributor() == newDistributor, "rewardDistributor should be updated");
    }
}
